// Pages that load their lists with JavaScript and need a rendered read. One entry per event.
const SCROLL = [{type: 'wait', milliseconds: 3000}];
for (let i = 0; i < 8; i++) { SCROLL.push({type: 'executeJavascript', script: 'window.scrollTo(0, document.body.scrollHeight)'}); SCROLL.push({type: 'wait', milliseconds: 2500}); }
SCROLL.push({type: 'scrape'});
const TARGETS = [
  {slug: 'ukisug-connect-2026', name: 'UKISUG Connect', market: 'UK', url: 'https://www.ukisugconnect.co.uk/event/home/agenda', exhibitors_url: 'https://www.ukisugconnect.co.uk/event/home/exhibitors', parser: 'cvent'}
];
return TARGETS.map(t => {
  const m = t.url.match(/^(https?:\/\/[^\/]+)(\/[^?#\s]*)?/);
  return {json: {...t, origin: m[1], path: m[2] || '/', scroll_actions: SCROLL}};
});

const plan = $('Plan').all();
return $input.all().map((r, i) => {
  const p = plan[i].json;
  const txt = String(r.json.data || '');
  let allowed = true, reason = 'ok';
  if (!p.parser) {
    allowed = false; reason = 'no_parser_for_' + p.origin;
  } else {
    const lines = txt.split(/\r?\n/).map(l => l.replace(/#.*/, '').trim()).filter(Boolean);
    let applies = false;
    const rules = [];
    for (const l of lines) {
      const m = l.match(/^([a-z-]+)\s*:\s*(.*)$/i);
      if (!m) continue;
      const k = m[1].toLowerCase(), v = m[2].trim();
      if (k === 'user-agent') applies = v === '*';
      else if (applies && (k === 'disallow' || k === 'allow')) rules.push([k, v]);
    }
    let best = null;
    for (const [k, v] of rules) {
      if (v && p.path.startsWith(v) && (!best || v.length > best[1].length)) best = [k, v];
    }
    if (best && best[0] === 'disallow') { allowed = false; reason = 'robots_disallow ' + best[1]; }
  }
  return {json: {...p, node: 'Gate', allowed, reason}};
});

const src = $('Gate').item.json;
const ag = $('Firecrawl').item.json || {};
const ex = $json || {};
const getHtml = r => {
  const s = r.data && r.data.actions && r.data.actions.scrapes;
  if (s && s.length) return String(s[s.length - 1].html || '');
  return String((r.data && (r.data.html || r.data.rawHtml)) || '');
};
const html = getHtml(ag);
const exHtml = getHtml(ex);
const shown = (html.match(/Showing (\d+) sessions/) || [])[1] || null;
const dec = s => String(s || '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&#x([0-9a-f]+);/gi, (m, h) => String.fromCharCode(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (m, d) => String.fromCharCode(+d))
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const base = {slug: src.slug, url: src.url, node: 'Parse', parser: src.parser};
if (!html) return {json: {...base, found: 0, error: 'firecrawl_error: ' + String(ag.error || ag.message || ('no html, success=' + ag.success)).slice(0, 200), rows: []}};

function inner(h, start) {
  let depth = 1; const re = /<(\/?)div\b[^>]*>/g; re.lastIndex = start; let m;
  while ((m = re.exec(h))) { if (m[1]) depth--; else depth++; if (depth === 0) return h.slice(start, m.index); }
  return h.slice(start, start + 800);
}
const people = [];
const open = /<div[^>]*class="[^"]*speakerInfo___[^"]*"[^>]*>/g;
let om;
while ((om = open.exec(html))) {
  const body = inner(html, open.lastIndex);
  const t = [...body.matchAll(/>([^<>]+)</g)].map(x => dec(x[1])).filter(Boolean);
  if (t.length === 2) people.push({name: t[0], title: '', company: t[1]});
  else if (t.length >= 3) people.push({name: t[0], title: t[1], company: t[t.length - 1]});
  else if (t.length === 1) people.push({name: t[0], title: '', company: ''});
}

// Exhibitors are sellers. A speaker from an exhibiting company is a vendor, not a buyer.
const norm = s => String(s || '').toLowerCase().replace(/\(.*?\)/g, ' ').replace(/&/g, ' and ')
  .replace(/\b(ltd|limited|gmbh|plc|inc|llc|uk|group|the|and|co|ag|sa|bv|software|technologies|technology|consulting|solutions)\b/g, ' ')
  .replace(/[^a-z0-9]+/g, '');
const exhibitors = [...new Set([...exHtml.matchAll(/ExhibitorsStyles__placeholder___[a-z0-9]+[^"]*"[^>]*>([^<]+)</g)].map(m => norm(dec(m[1]))).filter(Boolean))];
const isExhibitor = company => {
  const c = norm(company);
  if (!c) return false;
  return exhibitors.some(e => e === c || (e.length >= 5 && c.length >= 5 && (c.includes(e) || e.includes(c))));
};
const FUNC = [
  ['procurement', /procure|purchas|sourcing|einkauf|einkäuf|einkaeuf|beschaffung|supplier|\bcpo\b|\bbuyers?\b|category manag|indirect|\bspend\b/i],
  ['supply chain', /supply\s*(chain|officer)|\bscm\b|logistic|lieferkett|fulfil|warehouse|demand|planning|transport|materials?\s+manag|inventory|trade compliance|global trade|customs/i],
  ['finance ops', /finance|financial|accounting|payable|receivable|controll|treasury|\bcfo\b|shared service|business services|\bgbs\b|order[- ]to[- ]cash|procure[- ]to[- ]pay|\bp2p\b|\bo2c\b|\bap\b|\bar\b|credit|collections|billing|invoic|order management|\bcash\b/i],
  ['operations or IT', /operations|operating officer|information officer|\berp\b|\bsap\b|transformation|digital|\bcoo\b|\bcio\b/i]
];
const NONBUYER = /investor|venture|capital|angel|founder|professor|journalist|moderator|chefvolkswirt|economist|minister|politik|referent\b|\bhost\b|author|keynote/i;
const ACADEMIC = /universit|hochschule|fraunhofer|institut\b|akademie|academy/i;
const HIGH = /\b(chief|cpo|cfo|coo|ceo|cio|cto|president|vice president|vp|svp|evp|head|director|direktor\w*|vorstand\w*|leiter\w*|leitung|bereichsleit\w*|abteilungsleit\w*|geschäftsführ\w*|managing|einkaufsleiter\w*)\b/i;
const MID = /\b(manager|lead|senior|principal|teamleit\w*)\b/i;
const VENDOR = /\b(software|saas|ai|labs?|platform|cloud|analytics|robotics|technolog\w*|solutions?|consult\w*|advisory|startup|ventures?)\b/i;

function tree(p) {
  let fn = null;
  if (!NONBUYER.test(p.title) && !ACADEMIC.test(p.company)) for (const [label, re] of FUNC) if (re.test(p.title)) { fn = label; break; }
  if (!fn) return {tier: 'X', drop: true, detail: {path: 'function: no procurement, supply chain or finance role in title, so excluded'}};
  const sr = HIGH.test(p.title) ? 'high' : MID.test(p.title) ? 'mid' : 'low';
  if (sr === 'low') return {tier: 'C', detail: {function: fn, seniority: 'below manager', path: 'function yes (' + fn + '), seniority low, so C'}};
  if (sr === 'mid') return {tier: 'B', detail: {function: fn, seniority: 'manager', path: 'function yes (' + fn + '), seniority manager, so B'}};
  if (VENDOR.test(p.company)) return {tier: 'X', detail: {function: fn, seniority: 'senior', vendor: true, path: 'function yes (' + fn + '), seniority senior, company looks like a vendor, so X'}};
  if (fn === 'operations or IT') return {tier: 'B', detail: {function: fn, seniority: 'senior', vendor: false, path: 'function broad (operations or IT), seniority senior, not a vendor, so B'}};
  return {tier: 'A', detail: {function: fn, seniority: 'senior', vendor: false, path: 'function yes (' + fn + '), seniority senior, not a vendor, so A'}};
}


const OWN = /^(SAP\b|UKISUG\b)/i;
const seen = new Set(); const rows = []; const tiers = {A: 0, B: 0, C: 0, X: 0};
let dropped = 0, noCompany = 0, ownOrg = 0, vendorByExhibitor = 0, noTitle = 0, unverified = 0;
for (const p of people) {
  if (!p.name || !p.company) { noCompany++; continue; }
  const key = (p.name + '|' + p.company).toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);
  if (OWN.test(p.company)) { ownOrg++; continue; }
  const sells = isExhibitor(p.company);
  let tier, detail;
  if (p.title) {
    const r = tree(p);
    if (r.drop) { dropped++; continue; }
    tier = r.tier; detail = r.detail;
    if (sells && tier !== 'X') { tier = 'X'; detail = Object.assign({}, detail, {vendor: true, path: detail.path + '; company exhibits at the event, so it is a vendor, X'}); }
  } else {
    if (sells || VENDOR.test(p.company)) { vendorByExhibitor++; continue; }
    if (!exhibitors.length) { unverified++; continue; }
    noTitle++;
    tier = 'C';
    detail = {function: null, seniority: 'unknown', path: 'role not listed on the agenda; company is not on the exhibitor list, so it looks like a customer at an SAP user group event, C. Reviewer to confirm the buyer role'};
  }
  tiers[tier]++;
  rows.push({event_slug: src.slug, full_name: p.name, title: p.title || null, company: p.company, source_url: src.url,
    source_kind: 'speaker (rendered agenda)',
    data_lineage: 'Organiser agenda page (public), rendered with Firecrawl after a robots.txt check.',
    tier, score_detail: detail});
}
let error = null;
if (!people.length) error = 'no_speaker_cards_found (page rendered, ' + html.length + ' bytes, markup may have changed)';
else if (!exhibitors.length && !rows.length) error = 'exhibitor_list_missing (' + unverified + ' speakers held back because vendors could not be told apart)';
else if (!rows.length) error = 'no_buyer_leads_from_rendered_agenda (' + seen.size + ' speakers read)';
return {json: {...base, found: seen.size, exhibitors: exhibitors.length, dropped_by_tree: dropped, skipped_no_company: noCompany, own_org: ownOrg, vendor_by_exhibitor: vendorByExhibitor, held_back_no_exhibitor_list: unverified, no_title_tier_c: noTitle, sessions_shown: shown, tiers, error, rows}};
